      {
        "type": "notes",
        "id": "pratica-antagonismo-ed2026-notas",
        "title": "Minha versão do estudo",
        "prompt": "Você pode adaptar o exemplo e acrescentar suas observações.",
        "seed": "Curvas concentração-resposta relacionam exposição e efeito em um sistema definido. Emax indica resposta máxima observada no modelo; EC50 é a concentração que produz metade dessa resposta. Potência e eficácia são dimensões diferentes, e maior potência não implica maior benefício clínico.\n\nQuestão — A e B têm o mesmo Emax; EC50 de A é 2 e de B é 10 unidades. Qual é mais potente nesse ensaio?\nInterpretação — A, pois necessita menor concentração para produzir metade do mesmo máximo. A eficácia máxima é igual no ensaio. A comparação não estabelece superioridade clínica sem considerar exposição, segurança e contexto.\nBase de estudo — IUPHAR/BPS. The Concise Guide to PHARMACOLOGY 2025/26."
      }
